css:
:scope{display:block;width:100%}
.pw{--ink:#010A12;--bone:#EDE6D8;--stone:#E0D9CB;--sand:#BBAFA3;--oxblood:#321013;--mulberry:#5E3A3C;--clay:#8C5B46;--gilt:#C6A15B;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;letter-spacing:0;-webkit-font-smoothing:antialiased;text-align:left}
.pw *{box-sizing:border-box}
:where(.pw p,.pw h1,.pw h2,.pw h3,.pw ul,.pw ol,.pw li){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.in{max-width:1200px;margin:0 auto;padding:0 32px}
.narrow{max-width:1000px}
.pad{padding:160px 0}
.kick{margin:0;font-family:var(--label);font-weight:400;font-size:12px;line-height:18px;letter-spacing:.32em;text-transform:uppercase}
.rule{width:64px;height:1px;background:var(--clay);border:0;margin:0 0 40px}
.g-ink{background:var(--ink);color:var(--bone)}.g-ink .kick{color:var(--sand)}
.g-bone{background:var(--bone);color:var(--ink)}.g-bone .kick{color:var(--mulberry)}
.g-stone{background:var(--stone);color:var(--ink)}.g-stone .kick{color:var(--mulberry)}.g-stone .rule{background:var(--ink)}
.g-oxblood{background:var(--oxblood);color:var(--bone)}.g-oxblood .kick{color:var(--sand)}.g-oxblood .rule{background:var(--sand)}
.g-clay{background:var(--clay);color:var(--bone)}.g-clay .kick{color:var(--bone)}.g-clay .rule{background:var(--bone)}
.qt{font-family:var(--head);font-style:italic;font-weight:500;font-size:48px;line-height:1.15;text-wrap:balance;max-width:20em}
.at{margin-top:32px}
@media (max-width:767px){.pw{font-size:19px}.in{padding:0 20px}.pad{padding:88px 0}.qt{font-size:32px}}
.js-rv .rv{opacity:0;transform:translateY(16px);transition:opacity 1.3s ease,transform 1.3s ease}
.js-rv .rv.on{opacity:1;transform:none}
.js-rv .d1{transition-delay:.12s}
@media (prefers-reduced-motion:reduce){.js-rv .rv{opacity:1;transform:none;transition:none}}
